#!/usr/bin/env python3
"""Serialize individually authored judgements after reading the source passages.
The rows below are research decisions, not inferred from headings or keywords.
"""
from pathlib import Path
import csv,json,datetime
P=Path(__file__).parent
pkg='MPL_93_221-236+161-5'
source='sources/texts/pro/'+pkg+'_transcription.tex'
items=[]; entries=[]
def add(n,kind,cote,scans,lines,words,statement,reconstruction,check,reason,verdict='kept',merged=()):
    ident='SA23-'+str(200+n)
    nums=[n,*merged]
    items.append(dict(id=ident,sources=[pkg+'#'+str(k) for k in nums],kind=kind,cote=cote,scans=scans,lines=source+':'+lines,his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    for k in nums:entries.append(dict(entry_id=pkg+'#'+str(k),item_id=ident,verdict=verdict if k==n else 'merged',reason=reason if k==n else 'Same mathematical object or question as entry #'+str(n)+'. '+reason))
def save():
    (P/'items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
    with (P/'entries.tsv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(sorted(entries,key=lambda r:int(r['entry_id'].split('#')[1])))

